fn handle_line_defense(_version, rnd, player, data, line, _debug) -> bool

let ctx   = data.context;            // +0x8
let cache = data.cache;              // +0x0
let team  = player.info.team;        // +0x930
let enemy = 1 - team;                // 배열 길이 2 로 bounds-check

// --- 544: 이 라인이 이 판에 존재하는가 ---
if !rule_scope::line_exists(ctx, line) { return false }

// --- 549: 튜토리얼 게이트 (morgard_exists 가 인라인됨) ---
//   실제 IR: t = ctx.tutorial(+0x38); if (t - 1) <u 6 { return false }
//   → tutorial ∈ {First,TopSolo,Bottom,MidSolo,MidBottom,JungleOnly} 이면 false
if (ctx.tutorial as u8).wrapping_sub(1) < 6 { return false }

// --- 549: 적 팀의 에픽(모르가드) 미니언 버프가 남아 있어야 한다 ---
let moba = (*cache.game).get_game_mode()   // vtable slot +0x40
             .as_moba()                    // GameMode 태그 0 == Moba, 아니면 Option::unwrap_failed
             .unwrap();
if moba.epic_minion_buff_time[enemy] == 0 { return false }   // = remain_epic_time(enemy)

// --- 553~559: 기준 타워 고르기 ---
// 553: cache.tower(line, team)
//   line==Top    -> top_tower[team]   .or(top_tower2[team])      (+0x180 / +0x190)
//   line==Mid    -> mid_tower[team]   .or(mid_tower2[team])      (+0x1a0 / +0x1b0)
//   line==Bottom -> bottom_tower[team].or(bottom_tower2[team])   (+0x1c0 / +0x1d0)
let mut tower: Option<&Entity> = cache.line_tower(line)[team]
                                   .or(cache.line_tower2(line)[team]);

// 554~559: 라인 타워가 모두 없으면 twin_towers[team] 중 라인 시작지점에 가장 가까운 것
let start = line.get_start_position(ctx.setting, team);          // 556, (i64,i64)
tower = tower.or(
    cache.twin_towers[team].iter()                               // +0x130 + team*32
        .min_by_key(|t| {                                        // 555
            let d = line.get_start_position(ctx.setting, player.info.team); // 556 (클로저 안에서 재계산)
            let dx = abs_diff(t.x, d.0);                         // 557, Entity +0x660
            let dy = abs_diff(t.y, d.1);                         //      Entity +0x668
            dx*dx + dy*dy                                        // 제곱거리(sqrt 없음)
        })                                                       // 동률이면 첫 원소 유지(compare <= 0 이면 acc 유지)
        .map(|t| *t)                                             // 559
);
let tower = match tower { Some(t) => t, None => return false };  // 565 부근(unwrap 이 널체크로 접힘)

// --- 567: 이 라인에 실제 위협이 있는가 ---
if !has_line_defense_threat(player, data, line, tower.id /*+0x5c0*/) { return false }

// --- 571~572: 기준 타워 근처의 '보이는' 적 챔피언 수 ---
let enemies = cache.champions(enemy, ctx.pool);   // bumpalo Vec<&Entity>
let bb = &data.blackboard[enemy];                 // Blackboard(744B)
let mut near_enemy_champion = 0usize;
for c in enemies {
    if !bb.is_recent_visible(cache.game, player, c) { continue }   // 짧은회로: 0 가산
    let dx = abs_diff(c.x, tower.x);
    let dy = abs_diff(c.y, tower.y);
    if dx*dx + dy*dy < 40000000001 { near_enemy_champion += 1 }    // 200000^2 + 1
}
// (enemies 는 여기서 drop — Vec/RawVec drop 호출, 언와인드 경로 있음)

// --- 575~578: 전략별 최종 판정 ---
let strategy = player.strategy(rnd, cache.game);          // 575, Strategy(24B)
let defense  = strategy.morgard_defense;                  // 576, +0xe (0=Gather,1=Battle)
return if defense == Battle {
    (near_enemy_champion - 1) <u 2      // 578: near ∈ {1,2}
} else {                                 // Gather
    near_enemy_champion > 1              // 578: near >= 2
};                                       // 585: ret

// 조기 false 경로 정리(IR 블록 %19 의 phi):
//   %6   진입      : line_exists == false
//   %14            : tutorial ∈ 1..=6
//   %38            : epic_minion_buff_time[enemy] == 0
//   %105           : 라인타워도 twin_tower 도 없음(둘 다 None)
//   %109           : has_line_defense_threat == false
//   %166           : 최종 판정값 %173
